package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import android.opengl.*;import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;import org.json.*;
public final class SkyCoverageInstrumentation extends SceneGpuInstrumentation {
 JSONObject trace(NativeSkyScene frame)throws Exception{int[] id={0};GLES20.glGenTextures(1,id,0);int tex=id[0];GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,tex);GLES20.glTexImage2D(GLES20.GL_TEXTURE_2D,0,GLES20.GL_RGBA,240,160,0,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,null);GLES20.glGenFramebuffers(1,id,0);int fbo=id[0];GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,fbo);GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER,GLES20.GL_COLOR_ATTACHMENT0,GLES20.GL_TEXTURE_2D,tex,0);ok(GLES20.glCheckFramebufferStatus(GLES20.GL_FRAMEBUFFER)==GLES20.GL_FRAMEBUFFER_COMPLETE,"trace FBO");GLES20.glDisable(GLES20.GL_SCISSOR_TEST);GLES20.glClearColor(0,0,0,0);GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT);ArrayList<NativeSceneDrawPlan.Draw> draws=new ArrayList<>();ArrayList<Integer> owners=new ArrayList<>();NativeWorldScene[] worlds=new NativeWorldScene[frame.scene.geometryCount()];for(int owner=0;owner<worlds.length;owner++){worlds[owner]=new NativeWorldScene(frame.scene.geometry(owner));NativeSceneDrawPlan plan=new NativeSceneDrawPlan(frame.scene.geometry(owner));for(int i=0;i<plan.count();i++){draws.add(plan.draw(i));owners.add(owner);}}
 ByteBuffer pixels=ByteBuffer.allocateDirect(153600);boolean[] covered=new boolean[38400];JSONArray commands=new JSONArray();int[] totals={0,0};try(NativeSceneGpu gpu=new NativeSceneGpu()){gpu.drawOverBackground(frame.scene,240,160,index->{try{pixels.position(0);GLES20.glReadPixels(0,0,240,160,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,pixels);int added=0,total=0;for(int at=10560;at<10560+15136;at++){int y=at/240,x=at%240;if((pixels.get(((159-y)*240+x)*4+3)&255)>127){total++;if(!covered[at]){covered[at]=true;added++;}}}NativeSceneDrawPlan.Draw d=draws.get(index);int owner=owners.get(index);JSONObject row=new JSONObject();row.put("command",index);row.put("owner",owner);row.put("serial",frame.scene.geometry(owner).serial);row.put("model",d.model);row.put("source_index",d.index);row.put("wall",d.wall);row.put("vertices",d.vertices);row.put("material_width",d.width);row.put("material_height",d.height);row.put("source_bounds",new JSONArray(new int[]{d.bounds.left,d.bounds.right,d.bounds.top,d.bounds.bottom}));row.put("new_sky_cells",added);row.put("covered_sky_cells",total);if(!d.model){NativeWorldScene.Surface surface=worlds[owner].surface(d.index);row.put("mode",surface.mode);row.put("identity",new JSONArray(surface.identity()));}commands.put(row);totals[0]=total;if(added>0)totals[1]++;}catch(Exception e){throw new RuntimeException(e);}});}
 ok(GLES20.glGetError()==0,"trace readback");GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,0);GLES20.glDeleteFramebuffers(1,new int[]{fbo},0);GLES20.glDeleteTextures(1,new int[]{tex},0);JSONObject result=new JSONObject();result.put("kind",frame.scene.kind);result.put("split",frame.scene.splitRow);result.put("sky_cells_covered",totals[0]);result.put("commands_adding_coverage",totals[1]);result.put("commands",commands);return result;}
 public void onStart(){Bundle result=new Bundle();boolean live=false;try{File dir=new File(getTargetContext().getFilesDir(),"sky-scene-fixtures");startGl();live=true;JSONArray frames=new JSONArray();for(String kind:new String[]{"whole","split"})frames.put(trace(new NativeSkyScene(Files.readAllBytes(new File(dir,"sky-scene-"+kind+".nsb").toPath()))));JSONObject report=new JSONObject();report.put("result","PASS_SOURCE_COMMAND_SKY_COVERAGE_TRACE");report.put("frames",frames);report.put("renderer",renderer);report.put("rendering_changed",false);report.put("game_steps",0);try(FileOutputStream out=getTargetContext().openFileOutput("sky-coverage-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("stream","FAIL: "+e);finish(Activity.RESULT_CANCELED,result);}finally{if(live)endGl();}}
}
